import * as THREE from 'three';
// One metre is represented by the stream's five world units.
export function boardLayout(lengths){let end=2.5;return lengths.map(length=>{const width=length*.05,start=end;end+=width;return {length,width,start,end,center:(start+end)/2};});}
export function createBridgeBuilder({scene,camera,bridge,onFinish}){
 const panel=document.createElement('section');panel.id='bridge-builder';panel.hidden=true;panel.setAttribute('aria-label','Build and compare the bridge');panel.innerHTML='<div class="bridge-copy"><small>BUILD OUR WAY HOME</small><h2 id="bridge-title">Place the first board</h2><p id="bridge-message" role="status">Join the boards end to end.</p></div><button id="bridge-place" class="primary">Place board 1</button><button id="bridge-cancel">Back to boards</button>';document.body.append(panel);
 const title=panel.querySelector('h2'),message=panel.querySelector('p'),button=panel.querySelector('#bridge-place');
 const guides=new THREE.Group();scene.add(guides);guides.visible=false;
 const labels=[];let active=false,items=[],boards=[],result=null,phase=0,animation=null;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function clear(group){group.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});group.clear();}
 function label(text,pos,kind=''){const el=document.createElement('span');el.className='bridge-length '+kind;el.textContent=text;el.hidden=true;document.body.append(el);const l={el,pos,show:false};labels.push(l);return l;}
 function line(a,b,color,dashed=false){const g=new THREE.BufferGeometry().setFromPoints([a,b]);const material=dashed?new THREE.LineDashedMaterial({color,dashSize:.13,gapSize:.08}):new THREE.LineBasicMaterial({color});const l=new THREE.Line(g,material);if(dashed)l.computeLineDistances();guides.add(l);return l;}
 function disposeLabels(){for(const l of labels)l.el.remove();labels.length=0;}
 function close(keep=false){active=false;animation=null;panel.hidden=true;document.body.classList.remove('bridge-building');guides.visible=false;disposeLabels();if(!keep){clear(bridge);bridge.visible=false;}onFinish(keep,boards,result);}
 function compare(){phase=2;button.disabled=false;const end=items[1].layout.end,sum=boards[0].length+boards[1].length,short=sum<100;colorResult(short);if(short){const gap=+(100-sum).toFixed(1);line(new THREE.Vector3(end,.26,1),new THREE.Vector3(7.5,.26,1),'#c95639',true);const l=label(`Gap ${gap} cm`,new THREE.Vector3((end+7.5)/2,.6,1),'gap');l.show=true;title.textContent='The boards do not reach!';message.textContent=`${boards[0].length} cm + ${boards[1].length} cm = ${sum} cm. Look at the gap to the far bank.`;message.dataset.translation=`两块板首尾相接，还差 ${gap} 厘米才能到对岸。`;button.textContent='Choose longer boards';}else{title.textContent='The boards reach the far bank!';message.textContent=`${boards[0].length} cm + ${boards[1].length} cm = ${sum} cm. ${sum===100?'An exact fit!':`${+(sum-100).toFixed(1)} cm rests on the far bank.`}`;message.dataset.translation='两块板接起来已跨过100厘米宽的河。多出的部分在对岸。';button.textContent=result.ok?'Cross the bridge': 'Back to the meadow';if(!result.ok){message.textContent+=' Defeat the guardian before crossing.';message.dataset.translation='长度已足够，但还需要击败守卫才能通关。';}}
 }
 function colorResult(short){const marker=new THREE.Mesh(new THREE.BoxGeometry(.07,.08,1.9),new THREE.MeshBasicMaterial({color:short?'#c95639':'#39856a'}));marker.position.set(items[1].layout.end,.29,1);guides.add(marker);}
 function place(){if(animation)return;if(phase===2){close(result.ok);return;}const item=items[phase];button.disabled=true;title.textContent=phase===0?'Placing board 1…':'Joining board 2…';message.textContent=phase===0?'Start at the near bank.':'Put the next board against the end of the first.';animation={item,index:phase,time:0,start:item.mesh.position.clone(),duration:reduced?.01:1.3};}
 button.onclick=place;panel.querySelector('#bridge-cancel').onclick=()=>close(false);
 function start(chosen,evaluation){clear(bridge);clear(guides);disposeLabels();boards=chosen.map(b=>({...b}));result=evaluation;phase=0;active=true;animation=null;bridge.visible=true;bridge.position.set(0,0,0);guides.visible=true;panel.hidden=false;document.body.classList.add('bridge-building');button.disabled=false;title.textContent='Place the first board';message.textContent='The river is 1 m wide. Join two boards end to end.';message.dataset.translation='河宽1米。先放第一块板，再把第二块接在末端。';button.textContent=`Place board 1 · ${boards[0].length} cm`;
 const rulerY=.2,z=-.45;line(new THREE.Vector3(2.5,rulerY,z),new THREE.Vector3(7.5,rulerY,z),'#fff5b8');for(let i=0;i<=10;i++)line(new THREE.Vector3(2.5+i*.5,rulerY,z-.08),new THREE.Vector3(2.5+i*.5,rulerY,z+.08),'#fff5b8');
 const riverLabel=label('River width · 1 m = 100 cm',new THREE.Vector3(5,.45,-1),'river');riverLabel.show=true;for(const [x,text]of [[2.5,'0 cm'],[7.5,'100 cm']]){const l=label(text,new THREE.Vector3(x,.5,-.4));l.show=true;}
 items=boardLayout(boards.map(b=>b.length)).map((layout,i)=>{const board=new THREE.Group();bridge.add(board);const material=new THREE.MeshStandardMaterial({color:i?'#6099a6':'#cfa976',roughness:.85});const plank=new THREE.Mesh(new THREE.BoxGeometry(layout.width,.16,1.8),material);plank.castShadow=true;plank.receiveShadow=true;board.add(plank);for(const offset of [-.55,0,.55]){const grain=new THREE.Mesh(new THREE.BoxGeometry(layout.width*.92,.005,.016),new THREE.MeshStandardMaterial({color:i?'#397b89':'#9c743d'}));grain.position.set(0,.083,offset);board.add(grain);}board.position.set(-1-i*.7,.3,2.8+i*1.4);board.rotation.y=i?-.18:.14;const l=label(`${layout.length} cm`,new THREE.Vector3(),i?'second':'first');l.show=true;return {mesh:board,layout,label:l};});
 }
 function update(dt){if(!active)return;const maxEnd=Math.max(7.5,...items.map(i=>i.layout.end));const aim=new THREE.Vector3((2.5+maxEnd)/2,.1,1);const zoom=Math.max(1,(maxEnd-2.5)/5,1/camera.aspect);const desired=aim.clone().add(new THREE.Vector3(.2,9*zoom,7.5*zoom));camera.position.lerp(desired,reduced?1:Math.min(1,dt*4));camera.lookAt(aim);if(animation&&!window.wordHelpActive){const a=animation;a.time+=dt;const t=Math.min(1,a.time/a.duration),ease=t*t*(3-2*t);a.item.mesh.position.copy(a.start).lerp(new THREE.Vector3(a.item.layout.center,.21,1),ease);a.item.mesh.position.y+=reduced?0:Math.sin(Math.PI*t)*1.1;a.item.mesh.rotation.y*=1-ease;if(t===1){animation=null;phase++;button.disabled=false;if(phase===1){title.textContent='Now connect the second board';message.textContent='Keep the ends touching. No overlap and no gap.';message.dataset.translation='第二块接在第一块末端：不重叠，也不留缝。';button.textContent=`Place board 2 · ${boards[1].length} cm`;}else compare();}}
 for(const item of items)item.label.pos.copy(item.mesh.position).add(new THREE.Vector3(0,.4,0));for(const l of labels){const p=l.pos.clone().project(camera);l.el.hidden=!l.show||p.z>1||p.z< -1;l.el.style.left=(p.x*.5+.5)*innerWidth+'px';l.el.style.top=(-p.y*.5+.5)*innerHeight+'px';}
 }
 return {get active(){return active;},start,update,cancel(){if(active)close(false);},reset(){if(active)close(false);clear(bridge);clear(guides);disposeLabels();}};
}
